import numpy as np
from collections import deque

def get_connected_component(grid, start_pos):
    """Get connected component starting from a position using 4-connectivity"""
    height, width = grid.shape
    i, j = start_pos
    if grid[i, j] == 0:
        return [], i, j

    value = grid[i, j]
    visited = set()
    queue = deque([(i, j)])
    visited.add((i, j))

    while queue:
        ci, cj = queue.popleft()
        for di, dj in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            ni, nj = ci + di, cj + dj
            if 0 <= ni < height and 0 <= nj < width:
                if grid[ni, nj] == value and (ni, nj) not in visited:
                    visited.add((ni, nj))
                    queue.append((ni, nj))

    return visited, value

