import numpy as np
from collections import deque

# Quick function to find connected components
def get_largest_component_info(grid):
    height, width = grid.shape
    visited = set()
    value_info = {}

    for i in range(height):
        for j in range(width):
            if grid[i, j] == 0 or (i, j) in visited:
                continue
            value = grid[i, j]
            # BFS to find connected component
            queue = deque([(i, j)])
            component = []
            visited.add((i, j))

            while queue:
                ci, cj = queue.popleft()
                component.append((ci, cj))

                for di, dj in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    ni, nj = ci + di, cj + dj
                    if 0 <= ni < height and 0 <= nj < width:
                        if grid[ni, nj] == value and (ni, nj) not in visited:
                            visited.add((ni, nj))
                            queue.append((ni, nj))

            if value not in value_info:
                value_info[value] = {'total': 0, 'largest': 0, 'regions': []}
            value_info[value]['total'] += len(component)
            value_info[value]['regions'].append(len(component))
            if len(component) > value_info[value]['largest']:
                value_info[value]['largest'] = len(component)

    return value_info

